    ...trusted.policyLiterals.map(v => v.ref), ...trusted.effectReceipts.map(v => v.ref), ...(trusted.productProfiles ?? []).map(v => v.ref)];
  if (new Set(refs).size !== refs.length) return "MALFORMED";
  return null;
}

function parseVerdict(result: unknown, trusted: TrustedContext): "PASS" | "FAIL" | "UNCERTAIN" | null {
  try {
    const text = typeof result === "string" ? result : JSON.stringify(result);
    if (typeof text !== "string" || Buffer.byteLength(text) > 4096) return null;
    const v = JSON.parse(text) as Record<string, unknown>;
    if (!v || Array.isArray(v) || Object.keys(v).sort().join(",") !== "verdict,violations" ||
      typeof v.verdict !== "string" || !["PASS", "FAIL", "UNCERTAIN"].includes(v.verdict) || !Array.isArray(v.violations) || v.violations.length > 16) return null;
    const claims = trusted.protectedClaims.flatMap(c => { const p = ProtectedClaimV1Schema.safeParse(c); return p.success ? [p.data.claimId] : []; });
    const refs = new Set([...claims, ...trusted.boundSubjects.map(v => v.ref), ...trusted.policyLiterals.map(v => v.ref),
      ...trusted.effectReceipts.map(v => v.ref), ...(trusted.productProfiles ?? []).map(v => v.ref)]);
    for (const violation of v.violations) {
      if (!violation || typeof violation !== "object" || Array.isArray(violation) ||
        Object.keys(violation).sort().join(",") !== "kind,protectedRef" || !kinds.has(violation.kind) ||
        (violation.protectedRef !== null && !refs.has(violation.protectedRef))) return null;
    }
    if (v.verdict === "PASS" && v.violations.length > 0) return null;
    return v.verdict as "PASS" | "FAIL" | "UNCERTAIN";
  } catch { return null; }
}

/** Call immediately before send eligibility with a current code-owned readback. */
export function finalGate(input: { expected: VerifierBinding; response: VerifierResponse;
  current: TrustedContext; finalDraft: string; now: Date; fallback?: { id: string; text: string } }): TerminalOutcome {
  const { expected, response, current, finalDraft, now } = input;
  if (current.state.recipient !== expected.recipient) return terminal("NO_SEND", "RECIPIENT");
  const problem = hardPrecheck(current, finalDraft, now);
  if (problem && ["PRIVACY", "PERMISSION", "RECIPIENT"].includes(problem)) return terminal("NO_SEND", problem);
  if (problem === "STALE") return terminal("HANDOFF", "STALE");
  if (problem) return { ...terminalFallback(input.fallback?.id, input.fallback?.text), reason: problem };
  if (response.kind !== "VERDICT") return { ...terminalFallback(input.fallback?.id, input.fallback?.text), reason: response.kind };
  const currentBinding = makeBinding(expected.requestId, finalDraft, current);
  if (expected.trustedSnapshotId !== currentBinding.trustedSnapshotId) {
    // Snapshot covers permissions, recipient, revision, binding, facts and receipts.
    return terminal("HANDOFF", "STALE");
  }
  for (const key of ["requestId", "finalDraftHash", "trustedSnapshotId", "stateRevision", "factSnapshotVersion", "recipient"] as const) {
    if (response.binding[key] !== expected[key] || currentBinding[key] !== expected[key]) return terminal("HANDOFF", "STALE");
  }
  const verdict = parseVerdict(response.result, current);
  if (verdict !== "PASS") return { ...terminalFallback(input.fallback?.id, input.fallback?.text), reason: verdict ?? "MALFORMED" };
  return { disposition: "SEND_ELIGIBLE", reason: "PASS", text: finalDraft, fallbackId: null };
}

## 5. Task 1 — Freeze Checkpoint A protocol and corpora

**Description:** Create the locked development protocol, identities and fixtures before any provider result is observed. This task is evaluation scaffolding only; it changes no production runtime behavior.

**Acceptance criteria:**

- [ ] Manifest fails closed when source/model/prompt/schema/context/binding/variance/threshold identities are missing or inconsistent, and A2/A3 provider preflight fails until the corresponding run-source SHA is sealed.
- [ ] A2 corpus contains the seven exact PR387 attacks, at least two non-literal paraphrases for each of the five previously escaped semantic families, required verifier-prompt-injection/context-confusion cases, mixed safe+unsafe replies, and safe controls from every spec-required category.
- [ ] A3 corpus preserves the four semantic families with at least concern=3, partial-evidence=3, correction/referent/defer=4, conditional-policy=3, plus 2–4 simple controls; each case contains raw dialogue/state/trusted truth, required outcomes and forbidden claims/actions.
- [ ] Runtime projections cannot expose evaluator-only fields such as caseId/split/attack-family/expected-safe-or-unsafe/required/forbidden/rubric labels to the conversation model or semantic verifier; captured provider requests are validated for absence of these fields.
- [ ] Terminal disposition/fallback behavior is frozen before provider results, including exact handling of FAIL/UNCERTAIN/timeout/malformed/provider-error/stale-snapshot outcomes and exact code-owned fallback IDs/text/hashes.

**Protocol details to freeze:**

